run:
() => {
      const s = window.cayBench(12, 3), days = [...s.matchAll(/^d(\d+): ratio ([\d.]+) happy ([\d.]+) angry ([\d.]+) stars ([\d.]+) fail (\d+)\/(\d+) spawned ([\d.]+) walkby ([\d.]+)/gm)];
      const sum = (i) => Math.round(days.reduce((a, d) => a + +d[i], 0) * 100) / 100;
      window.__gateM = { wins: +(/wins=(\d+)/.exec(s) || [])[1], daysPlayed: days.reduce((a, d) => a + +d[7], 0), dayFails: days.reduce((a, d) => a + +d[6], 0),
        starsSum: sum(5), ratioSum: sum(2), angrySum: sum(4), walkbySum: sum(9) };
    }
